package com.enterprise.workflow;

public class FeatureFlagService {
    // In Trunk-Based Development, long feature branches are replaced by feature flags
    // allowing code to merge to trunk safely while remaining dormant in production.
    private final FeatureToggleRepository toggleRepository;

    public FeatureFlagService(FeatureToggleRepository toggleRepository) {
        this.toggleRepository = toggleRepository;
    }

    public void executeNewWorkflow() {
        if (toggleRepository.isEnabled("v2-engine-refactor")) {
            runOptimizedPipeline();
        } else {
            runLegacyPipeline();
        }
    }

